-- UUID v7 hecho a mano para PostgreSQL 16: 48 bits de hora + versión 7 + bits al azar
create function uuid7_at(ms bigint) returns uuid language sql volatile as $$
  with r as (select uuid_send(gen_random_uuid()) as b)
  select encode(set_byte(overlay(b placing substring(int8send(ms) from 3) from 1 for 6),
                         6, (get_byte(b, 6) & 15) | 112), 'hex')::uuid from r
$$;

-- claves generadas de antemano (en la v7, 10 claves por milisegundo)
create table k_id as select g::bigint as id from generate_series(1, 3000000) g;
create table k_v4 as select gen_random_uuid() as id from generate_series(1, 3000000);
create table k_v7 as select uuid7_at(1795000000000 + g / 10) as id from generate_series(1, 3000000) g;

-- tres tablas iguales salvo el tipo de la clave
create table t_id (id bigint primary key, destinatario text not null, peso_kg int not null);
create table t_v4 (id uuid   primary key, destinatario text not null, peso_kg int not null);
create table t_v7 (id uuid   primary key, destinatario text not null, peso_kg int not null);
insert into t_id select id, 'Cliente ' || right(id::text, 3), 10 from k_id;   -- y lo mismo con t_v4 y t_v7

